#!/bin/bash\n\necho \"🚀 Setting up Studio AI...\"\necho \"\"\n\n# Check Node.js\nif ! command -v node &> /dev/null; then\n    echo \"❌ Node.js not found. Please install Node.js 18+ first.\"\n    exit 1\nfi\n\necho \"✅ Node.js found: $(node --version)\"\necho \"\"\n\n# Install backend dependencies\necho \"📦 Installing backend dependencies...\"\nnpm install\n\nif [ $? -ne 0 ]; then\n    echo \"❌ Failed to install backend dependencies\"\n    exit 1\nfi\n\necho \"✅ Backend dependencies installed\"\necho \"\"\n\n# Install frontend dependencies\necho \"📦 Installing frontend dependencies...\"\ncd client 2>/dev/null || {\n    echo \"⚠️  Creating React frontend...\"\n    npx create-react-app client\n    cd client\n}\n\nnpm install\n\nif [ $? -ne 0 ]; then\n    echo \"❌ Failed to install frontend dependencies\"\n    exit 1\nfi\n\necho \"✅ Frontend dependencies installed\"\ncd ..\necho \"\"\n\n# Setup environment\necho \"⚙️ Setting up environment...\"\nif [ ! -f .env ]; then\n    cp .env.example .env\n    echo \"✅ Created .env file (configure it before running)\"\nelse\n    echo \"✅ .env file already exists\"\nfi\n\necho \"\"\n\n# Create necessary directories\necho \"📁 Creating directories...\"\nmkdir -p uploads outputs models logs\necho \"✅ Directories created\"\n\necho \"\"\necho \"================================================================\"\necho \"✅ Studio AI Setup Complete!\"\necho \"================================================================\"\necho \"\"\necho \"📖 Next steps:\"\necho \"1. Edit .env file with your GPU settings\"\necho \"2. Download AI models (Open-Sora, Stable Video, Real-ESRGAN)\"\necho \"3. Run: npm run dev\"\necho \"\"\necho \"🌐 Access at: http://localhost:3000\"\necho \"📡 Backend: http://localhost:5000\"\necho \"\"\necho \"🎉 Happy creating!\"\necho \"================================================================\"\n"
